.eon8-live-page .uk-navbar-left img {
    height: 60px;
    width: auto;
    object-fit: contain;
    transition: height 0.35s ease;
    display: block;
    margin-top:-10px;
}
.eon8-live-page .uk-navbar {
    display: flex !important;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    position: relative;
    z-index: 1;
}
.eon8-live-page .uk-navbar-left {
    display: flex !important;
    align-items: center;
    flex-direction: row;
    gap: 80px !important;
    flex-wrap: nowrap;
}
.eon8-live-page .uk-navbar-right {
    display: flex !important;
    align-items: center;
    margin-left: auto;
}
.eon8-live-page .uk-navbar-nav > li > .uk-navbar-dropdown {
    left: 50% !important;
    transform: translateX(-50%) !important;
    right: auto !important;
}
.eon8-live-page .uk-navbar-nav {
    display: flex !important;
    align-items: center;
    flex-direction: row;
    gap: 5px;
    list-style: none;
    margin: 0;
    padding: 0;
}
.eon8-live-page .uk-navbar-nav > li {
    display: flex;
    align-items: center;
    position: relative;
    white-space: nowrap;
}
.eon8-live-page .uk-navbar-nav > li > a {
    display: flex;
    align-items: center;
    padding: 6px 10px;
    font-size: 14px;
    line-height: 1;
    text-decoration: none;
    position: relative;
}
.eon8-live-page .uk-navbar-nav > li > a::after {
    content: "";
    position: absolute;
    bottom: 0;
    left: 10px;
    right: 10px;
    height: 2px;
    transform: scaleX(0);
    transition: transform 0.3s ease;
    transform-origin: left;
}
.eon8-live-page .uk-navbar-nav > li > a:hover::after {
    transform: scaleX(1);
}
@media (max-width: 1024px) {.eon8-live-page .uk-navbar-left img {
        height: 50px;
    }
.eon8-live-page .uk-navbar-nav {
        gap: 5px;
    }}
@media (max-width: 768px) {.eon8-live-page .uk-navbar-left img {
        height: 45px;
    }
.eon8-live-page .uk-navbar-nav {
        display: none !important;
    }}
@media (max-width: 480px) {.eon8-live-page .uk-navbar-left img {
        height: 38px;
    }}
.eon8-live-page .meta-hero {
    padding: 60px 20px;
    text-align: left;

    color: #fff;
    font-family: Arial, sans-serif;
}
.eon8-live-page .meta-hero h1 {
    font-size: 42px;
    margin-bottom: 20px;
    line-height: 1.3;
    color: #fff;
}
.eon8-live-page .meta-hero p {
    font-size: 18px;
    max-width: 700px;
    margin: auto;
    line-height: 1.7;
}
.eon8-live-page .meta-btn {
    margin-top: 30px;
    display: inline-block;
    padding: 12px 28px;
    background: #fff;
    color: #000;
    border-radius: 30px;
    text-decoration: none;
    font-weight: bold;
    transition: 0.3s;
}
.eon8-live-page .meta-btn:hover {
    background: #fff0;
}
.eon8-live-page .vrblue-section {
    padding: 0px 20px;
    background: #ffffff;
    font-family: Arial, sans-serif;
}
.eon8-live-page .vrblue-container {
    max-width: 1200px;
    margin: auto;
}
.eon8-live-page .vrblue-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 25px;
}
.eon8-live-page .vrblue-card {
    background: #ffffff;
    border-radius: 16px;
    padding: 25px;
    text-align: center;
    border: 1px solid #e0e7ff;
    box-shadow: 0 10px 25px rgba(59,130,246,0.08);
    transition: 0.3s ease;
}
.eon8-live-page .vrblue-card:hover {
    transform: translateY(-8px);
    box-shadow: 0 15px 35px rgba(59,130,246,0.2);
}
.eon8-live-page .vrblue-icon {
    width: 55px;
    height: 55px;
    margin: auto;
    margin-bottom: 15px;
    background: #2563eb;
    color: #fff;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 22px;
}
.eon8-live-page .vrblue-title {
    font-size: 18px;
    font-weight: bold;
    margin-bottom: 8px;
    color: #111;
}
.eon8-live-page .vrblue-desc {
    font-size: 14px;
    color: #555;
    line-height: 1.6;
}
.eon8-live-page .vrevent-section {
