.eon8-live-page .vrexp-section {
    padding: 0px 20px;
    background: #ffffff;
    font-family: Arial, sans-serif;
}
.eon8-live-page .vrexp-container {
    max-width: 1130px;
    margin: auto;
}
.eon8-live-page .vrexp-header {
    text-align: center;
    margin-bottom: 50px;
}
.eon8-live-page .vrexp-header h2 {
    font-size: 32px;
    margin-bottom: 10px;
    color: #222;
}
.eon8-live-page .vrexp-header p {
    font-size: 16px;
    color: #555;
    max-width: 750px;
    margin: auto;
}
.eon8-live-page .vrexp-block {
    display: flex;
    align-items: center;
    gap: 0px;
    background: #f3f4f6;
    padding: 40px;
    margin-bottom: 30px;
    border-radius: 10px;
    flex-wrap: wrap;
}
.eon8-live-page .vrexp-block.reverse {
    flex-direction: row-reverse;
}
.eon8-live-page .vrexp-img {
    flex: 1;
}
.eon8-live-page .vrexp-img img {
    width: 60%;
}
.eon8-live-page .vrexp-text {
    flex: 1;
}
.eon8-live-page .vrexp-text h3 {
    font-size: 26px;
