}
.eon8-live-page .vrframe-section {
    padding: 0px 20px;
    background: #ffffff;
    font-family: Arial, sans-serif;
}
.eon8-live-page .vrframe-container {
    max-width: 1300px;
    margin: auto;
}
.eon8-live-page .vrframe-header {
    text-align: center;
    margin-bottom: 60px;
}
.eon8-live-page .vrframe-header h2 {
    font-size: 32px;
    color: #1d4ed8;
    margin-bottom: 10px;
}
.eon8-live-page .vrframe-header p {
    font-size: 16px;
    color: #555;
    max-width: 800px;
    margin: auto;
    line-height: 1.7;
}
.eon8-live-page .vrframe-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 30px;
}
.eon8-live-page .vrframe-card {
    background: #ffffff;
    border: 1px solid #e0e7ff;
    border-radius: 16px;
    padding: 25px;
    position: relative;
    box-shadow: 0 10px 25px rgba(59,130,246,0.08);
    transition: 0.3s;
}
.eon8-live-page .vrframe-card:hover {
    transform: translateY(-6px);
    box-shadow: 0 15px 35px rgba(59,130,246,0.2);
}
.eon8-live-page .vrframe-number {
    position: absolute;
    top: -15px;
    left: 20px;
    background: #2563eb;
    color: #fff;
    font-size: 14px;
    padding: 6px 12px;
    border-radius: 20px;
    font-weight: bold;
}
.eon8-live-page .vrframe-icon {
    font-size: 22px;
    color: #2563eb;
    margin-bottom: 10px;
}
.eon8-live-page .vrframe-title {
    font-size: 18px;
    font-weight: bold;
    margin-bottom: 8px;
    color: #111;
}
.eon8-live-page .vrframe-desc {
    font-size: 14px;
    color: #555;
    line-height: 1.6;
}
.eon8-live-page .vrfaqb-section {
    padding: 0px 20px;
    background: #1e3a8a;
    font-family: Arial, sans-serif;
    margin-bottom: 30px;
}
.eon8-live-page .vrfaqb-container {
    max-width: 900px;
    margin: auto;
}
.eon8-live-page .vrfaqb-header {
    text-align: center;
    margin-bottom: 40px;
}
.eon8-live-page .vrfaqb-header h2 {
    font-size: 30px;
    color: #ffffff;
}
.eon8-live-page .vrfaqb-item {
    background: #ffffff;
    border-radius: 10px;
    margin-bottom: 15px;
    overflow: hidden;
    box-shadow: 0 8px 20px rgba(0,0,0,0.15);
}
.eon8-live-page .vrfaqb-question {
    font-size: 17px;
    font-weight: bold;
    cursor: pointer;
    padding: 15px 20px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    color: #111;
    transition: 0.3s;
}
.eon8-live-page .vrfaqb-question:hover {
    color: #1d4ed8;
}
.eon8-live-page .vrfaqb-icon {
    font-size: 18px;
    color: #1d4ed8;
    transition: 0.3s;
}
.eon8-live-page .vrfaqb-answer {
    max-height: 0;
    overflow: hidden;
    transition: 0.4s ease;
    padding: 0 20px;
}
.eon8-live-page .vrfaqb-answer p {
    font-size: 15px;
    color: #555;
    line-height: 1.6;
    margin-bottom: 15px;
}
.eon8-live-page .vrfaqb-item.active .vrfaqb-answer {
    max-height: 220px;
}
.eon8-live-page .vrfaqb-item.active .vrfaqb-icon {
    transform: rotate(45deg);
}
